import sys

def max_sq_brute(matrix):
    m, n = len(matrix), len(matrix[0])
    best = 0
    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 0: continue
            for k in range(1, min(m - i, n - j) + 1):
                ok = True
                for x in range(k):
                    for y in range(k):
                        if matrix[i + x][j + y] == 0:
                            ok = False; break
                    if not ok: break
                if ok:
                    best = max(best, k * k)
    return best

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    matrix = []
    idx = 2
    for _ in range(m):
        matrix.append([int(x) for x in data[idx:idx + n]])
        idx += n
    print(max_sq_brute(matrix))

import sys

def max_sq_opt(matrix):
    m, n = len(matrix), len(matrix[0])
    best = 0
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if matrix[i - 1][j - 1] == 1:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1
                if dp[i][j] > best: best = dp[i][j]
    return best * best

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    matrix = []
    idx = 2
    for _ in range(m):
        matrix.append([int(x) for x in data[idx:idx + n]])
        idx += n
    print(max_sq_opt(matrix))
